1	const PROCESSING_FEE = 5;
2	const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;
3	
4	const BASE_PREMIUM_BY_TYPE: Record<string, number> = {
5	  sword: 100,
6	  amulet: 60,
7	  staff: 80,
8	  potion: 40,
9	  rune: 25,
10	  moonstone: 25,
11	};
12	
13	const BLOCK_SIZE = 3;
14	const BLOCK_PRICE: Record<string, number> = {
15	  rune: 60,
16	  moonstone: 60,
17	};
18	
19	type QuoteItem = {
20	  type: string;
21	  material?: string;
22	  enchantment?: number;
23	  cursed?: boolean;
24	};
25	
26	type Customer = {
27	  yearsWithMHPCO: number;
28	};
29	
30	type QuoteStep = {
31	  op: "quote";
32	  items: QuoteItem[];
33	};
34	
35	const groupByType = (items: QuoteItem[]): Record<string, QuoteItem[]> => {
36	  const groups: Record<string, QuoteItem[]> = {};
37	  for (const item of items) {
38	    (groups[item.type] ??= []).push(item);
39	  }
40	  return groups;
41	};
42	
43	const isPricedAsBlock = (type: string, count: number): boolean =>
44	  count === BLOCK_SIZE && type in BLOCK_PRICE;
45	
46	const priceGroup = (type: string, items: QuoteItem[]): number =>
47	  isPricedAsBlock(type, items.length)
48	    ? BLOCK_PRICE[type]
49	    : items.length * BASE_PREMIUM_BY_TYPE[type];
50	
51	const assertKnownItemTypes = (items: QuoteItem[]): void => {
52	  for (const item of items) {
53	    if (!(item.type in BASE_PREMIUM_BY_TYPE)) {
54	      throw new Error(`Unknown item type: ${item.type}`);
55	    }
56	  }
57	};
58	
59	const calculateBasePremium = (items: QuoteItem[]): number => {
60	  const groupsByType = groupByType(items);
61	  return Object.entries(groupsByType).reduce(
62	    (sum, [type, groupItems]) => sum + priceGroup(type, groupItems),
63	    0
64	  );
65	};
66	
67	const CURSE_SURCHARGE_PERCENT = 50;
68	const HIGH_ENCHANTMENT_THRESHOLD = 5;
69	const HIGH_ENCHANTMENT_SURCHARGE_PERCENT = 30;
70	const LOYALTY_YEARS_THRESHOLD = 2;
71	const LOYALTY_DISCOUNT_PERCENT = 20;
72	const FOLLOW_UP_CONTRACT_DISCOUNT_PERCENT = 15;
73	
74	const calculateItemSurcharge = (items: QuoteItem[]): number =>
75	  items.reduce((sum, item) => {
76	    const itemBasePremium = BASE_PREMIUM_BY_TYPE[item.type];
77	    const surchargePercent =
78	      (item.cursed ? CURSE_SURCHARGE_PERCENT : 0) +
79	      ((item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD ? HIGH_ENCHANTMENT_SURCHARGE_PERCENT : 0);
80	    return sum + (itemBasePremium * surchargePercent) / 100;
81	  }, 0);
82	
83	const calculatePolicyModifierPercent = (
84	  customer: Customer,
85	  isFollowUpContract: boolean
86	): number => {
87	  const isLoyalCustomer = customer.yearsWithMHPCO >= LOYALTY_YEARS_THRESHOLD;
88	  return (
89	    FIRST_INSURANCE_SURCHARGE_PERCENT +
90	    (isLoyalCustomer ? -LOYALTY_DISCOUNT_PERCENT : 0) +
91	    (isFollowUpContract ? -FOLLOW_UP_CONTRACT_DISCOUNT_PERCENT : 0)
92	  );
93	};
94	
95	const quotePremium = (
96	  step: QuoteStep,
97	  customer: Customer,
98	  isFollowUpContract: boolean
99	): number => {
100	  assertKnownItemTypes(step.items);
101	  const basePremium = calculateBasePremium(step.items);
102	  const itemSurcharge = calculateItemSurcharge(step.items);
103	  const policyModifierPercent = calculatePolicyModifierPercent(customer, isFollowUpContract);
104	  const policyModifierAmount = (basePremium * policyModifierPercent) / 100;
105	  const premiumBeforeFee = basePremium + itemSurcharge + policyModifierAmount;
106	  return Math.ceil(premiumBeforeFee + PROCESSING_FEE);
107	};
108	
109	const BASE_INSURANCE_VALUE_BY_TYPE: Record<string, number> = {
110	  sword: 1000,
111	  amulet: 600,
112	  staff: 800,
113	  potion: 400,
114	  rune: 250,
115	  moonstone: 250,
116	};
117	
118	const CAP_MULTIPLIER = 2;
119	const DEDUCTIBLE = 100;
120	
121	type Damage = { itemType: string; amount: number };
122	type ClaimStep = {
123	  op: "claim";
124	  policy: number;
125	  incident: { cause: string; damages: Damage[] };
126	};
127	type Step = QuoteStep | ClaimStep;
128	
129	const insuranceSum = (items: QuoteItem[]): number =>
130	  items.reduce((sum, item) => sum + BASE_INSURANCE_VALUE_BY_TYPE[item.type], 0);
131	
132	const HIGH_ENCHANTMENT_CLAIM_THRESHOLD = 8;
133	const HIGH_ENCHANTMENT_REIMBURSEMENT_PERCENT = 50;
134	const FULL_REIMBURSEMENT_PERCENT = 100;
135	
136	// Note: the spec's "dragon-material" clause grants full reimbursement, which is
137	// numerically identical to the default (no-clause) case below — so `material`
138	// does not need to be inspected here. This is not an oversight; revisit if a
139	// future rule makes dragon-material's payout diverge from the default.
140	const reimbursementPercent = (item: QuoteItem): number =>
141	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_CLAIM_THRESHOLD
142	    ? HIGH_ENCHANTMENT_REIMBURSEMENT_PERCENT
143	    : FULL_REIMBURSEMENT_PERCENT;
144	
145	const damagePayout = (damage: Damage, policyItems: QuoteItem[]): number => {
146	  const item = policyItems.find((policyItem) => policyItem.type === damage.itemType)!;
147	  const reimbursement = (damage.amount * reimbursementPercent(item)) / 100;
148	  return reimbursement - DEDUCTIBLE;
149	};
150	
151	const claimPayout = (
152	  claimStep: ClaimStep,
153	  policyItems: QuoteItem[],
154	  cumulativePayout: number
155	): { payout: number; remainingCap: number } => {
156	  const cap = CAP_MULTIPLIER * insuranceSum(policyItems);
157	  const desiredPayout = claimStep.incident.damages.reduce(
158	    (sum, damage) => sum + damagePayout(damage, policyItems),
159	    0
160	  );
161	  const payout = Math.min(desiredPayout, cap - cumulativePayout);
162	  const remainingCap = cap - cumulativePayout - payout;
163	  return { payout, remainingCap };
164	};
165	
166	export const runScenario = (scenario: {
167	  customer: Customer;
168	  steps: Step[];
169	}): { results: ({ premium: number } | { payout: number; remainingCap: number })[] } => {
170	  const policyItemsByStepIndex: Record<number, QuoteItem[]> = {};
171	  const cumulativePayoutByPolicy: Record<number, number> = {};
172	  let quoteStepsSeen = 0;
173	  const results = scenario.steps.map((step, index) => {
174	    if (step.op === "claim") {
175	      const policyItems = policyItemsByStepIndex[step.policy];
176	      const cumulativePayout = cumulativePayoutByPolicy[step.policy] ?? 0;
177	      const result = claimPayout(step, policyItems, cumulativePayout);
178	      cumulativePayoutByPolicy[step.policy] = cumulativePayout + result.payout;
179	      return result;
180	    }
181	    const isFollowUpContract = quoteStepsSeen > 0;
182	    quoteStepsSeen += 1;
183	    policyItemsByStepIndex[index] = step.items;
184	    return { premium: quotePremium(step, scenario.customer, isFollowUpContract) };
185	  });
186	  return { results };
187	};
