166	export const runScenario = (scenario: {
167	  customer: Customer;
168	  steps: Step[];
169	}): { results: ({ premium: number } | { payout: number; remainingCap: number })[] } => {
170	  const policyItemsByStepIndex: Record<number, QuoteItem[]> = {};
171	  const cumulativePayoutByPolicy: Record<number, number> = {};
172	  let quoteStepsSeen = 0;
173	  const results = scenario.steps.map((step, index) => {
174	    if (step.op === "claim") {
175	      const policyItems = policyItemsByStepIndex[step.policy];
176	      const cumulativePayout = cumulativePayoutByPolicy[step.policy] ?? 0;
177	      const result = claimPayout(step, policyItems, cumulativePayout);
178	      cumulativePayoutByPolicy[step.policy] = cumulativePayout + result.payout;
179	      return result;
180	    }
181	    const isFollowUpContract = quoteStepsSeen > 0;
182	    quoteStepsSeen += 1;
183	    policyItemsByStepIndex[index] = step.items;
184	    return { premium: quotePremium(step, scenario.customer, isFollowUpContract) };
185	  });
186	  return { results };
187	};
